SELECT e.id
, _utf8mb4'SLEEP' COLLATE utf8mb4_0900_bin AS type , e.sleep_date AS event_date, e.end_time AS occurred_at , e.source_name COLLATE utf8mb4_0900_bin AS source_name , CONVERT(CONCAT('睡眠 ', e.duration_minutes, ' 分钟') USING utf8mb4) COLLATE utf8mb4_0900_bin AS summary
, JSON_OBJECT('startTime', REPLACE(CAST(e.start_time AS CHAR), ' ', 'T'), 'endTime', REPLACE(CAST(e.end_time AS CHAR), ' ', 'T'), 'sleepDate', CAST(e.sleep_date AS CHAR), 'durationMinutes', e.duration_minutes, 'sourceApp', e.source_app, 'deviceBrand', e.device_brand, 'deviceType', e.device_type, 'deviceModel', e.device_model, 'note', e.note) AS details_json
FROM sleep_records e WHERE e.user_id = #{userId}
AND e.id = #{id}
AND e.sleep_date BETWEEN #{q.startDate} AND #{q.endDate}
UNION ALL

SELECT e.id
, _utf8mb4'STEPS' COLLATE utf8mb4_0900_bin AS type , e.activity_date AS event_date, e.end_time AS occurred_at , e.source_name COLLATE utf8mb4_0900_bin AS source_name , CONVERT(CONCAT('步数 ', e.steps, ' 步') USING utf8mb4) COLLATE utf8mb4_0900_bin AS summary
, JSON_OBJECT('startTime', REPLACE(CAST(e.start_time AS CHAR), ' ', 'T'), 'endTime', REPLACE(CAST(e.end_time AS CHAR), ' ', 'T'), 'steps', e.steps, 'mode', e.mode, 'note', e.note) AS details_json
FROM step_records e WHERE e.user_id = #{userId}
AND e.id = #{id}
AND e.activity_date BETWEEN #{q.startDate} AND #{q.endDate}
UNION ALL

SELECT e.id
, _utf8mb4'WORKOUT' COLLATE utf8mb4_0900_bin AS type , e.activity_date AS event_date, e.start_time AS occurred_at , e.source_name COLLATE utf8mb4_0900_bin AS source_name , CONVERT(CONCAT(e.exercise_type, ' · ', e.duration_minutes, ' 分钟') USING utf8mb4) COLLATE utf8mb4_0900_bin AS summary
, JSON_OBJECT('exerciseType', e.exercise_type, 'startTime', REPLACE(CAST(e.start_time AS CHAR), ' ', 'T'), 'endTime', REPLACE(CAST(e.end_time AS CHAR), ' ', 'T'), 'durationMinutes', e.duration_minutes, 'planItemId', e.plan_item_id, 'note', e.note) AS details_json
FROM workout_records e WHERE e.user_id = #{userId}
AND e.id = #{id}
AND e.activity_date BETWEEN #{q.startDate} AND #{q.endDate}
UNION ALL

